  "version": "1.6.0",
  "plan": {
    "id": "starter_reconditioning_cycle_aware",
    "name": "2-Week Cycle-Aware Strength Starter",
    "description": "A 2-week introductory strength reconditioning plan phased around menstrual cycle: low-intensity, no heavy Valsalva, no high-intensity or jumping during flow days (cycle days 1-3). Starts 2026-06-01.",
    "type": "workout",
    "visibility": "private",
    "metadata": {
      "created_at": "2026-05-20T12:00:00Z",
      "updated_at": "2026-05-20T12:00:00Z",
      "created_by": "trainer_jane_doe",
      "difficulty": "beginner",
      "language": "en",
      "estimated_duration_days": 14
    },
    "goals": [
      {
        "id": "recondition_strength",
        "type": "primary",
        "category": "strength",
        "name": "Recondition for progressive strength",
        "description": "Build baseline strength and movement quality with cycle-aware intensity modulation.",
        "target": {
          "metric": "one_rm_kg",
          "target_value": 0,
          "unit": "kg",
          "measurement_type": "absolute"
        },
        "milestones": [
          {
            "id": "complete_week1",
            "name": "Complete week 1"
          },
          {
            "id": "complete_week2",
            "name": "Complete week 2"
          }
        ]
      }
    ],
    "requirements": {
      "min_age": 18,
      "fitness_level": [
        "recreational"
      ],
      "equipment": [
        {
          "id": "mat",
          "name": "exercise mat",
          "required": true
        },
        {
          "id": "dumbbells",
          "name": "adjustable dumbbells or light kettlebell",
          "required": false,
          "alternatives": [
            "resistance_band",
            "bodyweight"
          ]
        },
        {
          "id": "resistance_band",
          "name": "resistance band",
          "required": false,
          "alternatives": [
            "dumbbells"
          ]
        }
      ],
      "contraindications": [
        {
          "condition": "severe_primary_dysmenorrhea",
          "severity": "moderate",
          "action": "modify",
          "affected_activities": [
            "high_intensity_cardio",
            "heavy_barbell_lift",
            "plyometric_jumps"
          ]
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 5,
